#include <stdio.h>

int main() {
    int neighbours[5][3] = {{1, 2, -1}, {0, 3, -1}, {0, 3, 4}, {1, 2, -1}, {2, -1, -1}};
    int visited[5] = {0};
    int queue[10];
    int front = 0, rear = 0;
    queue[rear++] = 0;
    visited[0] = 1;
    while (front < rear) {
        int node = queue[front++];
        printf("%d ", node);
        for (int k = 0; k < 3 && neighbours[node][k] != -1; k++) {
            int next = neighbours[node][k];
            if (!visited[next]) {
                visited[next] = 1;
                queue[rear++] = next;
            }
        }
    }
    printf("\n");
    return 0;
}
